const http = require('http');
const server = http.createServer((req, res) => res.end('Hello'));

server.listen(3000, () => console.log('Server running...'));

// Listen for the termination signal from the OS (e.g., Docker or Ctrl+C)
process.on('SIGTERM', shutDown);
process.on('SIGINT', shutDown);

function shutDown() {
  console.log('\n[SYSTEM]: Received kill signal, shutting down gracefully...');

  // 1. Stop accepting NEW requests
  server.close(() => {
    console.log('[SYSTEM]: Closed out remaining connections.');

    // 2. Close database connections
    // mongoose.connection.close(false, () => {
    //   console.log('MongoDb connection closed.');

      // 3. Exit successfully
      console.log('[SYSTEM]: Goodbye!');
      process.exit(0);
    // });
  });

  // 4. Force kill after 10 seconds if it hangs
  setTimeout(() => {
    console.error('[SYSTEM]: Could not close connections in time, forcefully shutting down');
    process.exit(1);
  }, 10000);
}
